from dataclasses import dataclass, field, replace
from typing import Optional
import hashlib, json, time, random, pandas as pd

# ---- self-contained fallbacks (in case prior cells were reset) --------------
try:
    Transaction, LogEntry, make_entry, GENESIS_HASH, ReplicaState
except NameError:  # pragma: no cover
    GENESIS_HASH = "0" * 64
    @dataclass(frozen=True)
    class Transaction:
        client_id: str; request_id: str; op: str; key: Optional[str]
        value: Optional[bytes]; timestamp_ns: int; metadata: dict = field(default_factory=dict)
    @dataclass(frozen=True)
    class LogEntry:
        index: int; term: int; prev_hash: str; txn: Transaction
        committed_at_ns: Optional[int]; hash: str
    def make_entry(index, term, prev_hash, txn, committed_at_ns=None):
        h = hashlib.sha256()
        h.update(index.to_bytes(8, "big")); h.update(term.to_bytes(8, "big"))
        h.update(prev_hash.encode())
        h.update(json.dumps({"rid": txn.request_id, "op": txn.op, "k": txn.key,
                             "v": repr(txn.value)}, sort_keys=True).encode())
        return LogEntry(index, term, prev_hash, txn, committed_at_ns, h.hexdigest())
    @dataclass
    class ReplicaState:
        node_id: str; members: tuple; epoch: int = 0
        leader_id: Optional[str] = None; voted_for: Optional[str] = None
        log: list = field(default_factory=list); commit_index: int = 0
        applied_index: int = 0; match_index: dict = field(default_factory=dict)
        state_machine: dict = field(default_factory=dict)
        @property
        def quorum_size(self): return len(self.members) // 2 + 1
        @property
        def last_log_index(self): return len(self.log)
        @property
        def role(self):
            if self.leader_id is None: return "candidate"
            return "leader" if self.leader_id == self.node_id else "follower"


# ============================ fault schedule ================================
FAULT_KINDS = ("partition", "delay", "reorder", "drop", "crash", "restart",
               "clock_skew", "disk_corrupt", "disk_fail")


@dataclass(frozen=True)
class Fault:
    step: int
    kind: str
    target: str
    params: dict = field(default_factory=dict)
    duration_steps: int = 0


def build_schedule(rng: random.Random, n_steps: int, nodes: tuple) -> list:
    """Deterministically generate a schedule of faults from a seeded RNG."""
    sched = []
    for s in range(1, n_steps + 1):
        if rng.random() < 0.55:               # ~55% of steps carry a fault
            kind = rng.choice(FAULT_KINDS)
            target = rng.choice(nodes)
            p, dur = {}, 0
            if kind == "partition":
                other = rng.choice([n for n in nodes if n != target])
                p = {"group_a": [target], "group_b": [n for n in nodes if n != target]}
                dur = rng.randint(1, 3)
            elif kind == "delay":
                p = {"ms": rng.choice([50, 150, 400, 1200])}
            elif kind == "reorder":
                p = {"swap": rng.randint(1, 4)}
            elif kind == "drop":
                p = {"which": rng.choice(["append", "appendack", "vote"])}
            elif kind == "clock_skew":
                p = {"skew_ns": rng.choice([-5_000_000, -500_000, 500_000, 5_000_000])}
            elif kind == "disk_corrupt":
                p = {"index": rng.randint(1, 6)}
            elif kind == "disk_fail":
                p = {"fsync_ok": False}
                dur = rng.randint(1, 3)
            sched.append(Fault(step=s, kind=kind, target=target, params=p,
                               duration_steps=dur))
    return sched
